// Pictures, shapes and comments in the workbook view: what reaches the canvas,
// how it follows scrolling, frozen panes and inserted rows, and the box that
// shows a comment beside its cell.
//
// Pixels are sampled at positions written out by hand from the default sizes
// of a sheet (header 72 x 22, columns 64 wide, rows 20 high). Every workbook
// is generated by code. Everything is kept within columns A to D, so that a
// phone shows it as well.
import type { Page } from '@playwright/test';
import {
  chartFrame,
  comment,
  commentsXml,
  connector,
  drawingWorkbook,
  group,
  outline,
  para,
  pic,
  run,
  solid,
  sp,
  twoCell,
  txBody,
  vmlNote,
  vmlXml,
  xfrm,
} from '../test/sheet-drawing-fixtures';
import { png } from './fixtures/docx';
import { expect, test } from './helpers';

const HEADER_WIDTH = 72;
const HEADER_HEIGHT = 22;
const COLUMN_WIDTH = 64;
const ROW_HEIGHT = 20;

const RED = [220, 0, 0];
const BLUE = [0, 0, 220];
const WHITE = [255, 255, 255];
const GREEN = [0, 176, 80];
const PLACEHOLDER = [241, 243, 244];
const NOTE = [255, 255, 225];
const MARK = [224, 40, 30];

function once<T>(make: () => Promise<T>): () => Promise<T> {
  let value: Promise<T> | undefined;
  return () => (value ??= make());
}

/** Left half red, right half blue. */
const twoColours = () => png(40, 20, [220, 0, 0], [0, 0, 220]);

const cells = '<sheetData><row r="1"><c r="A1"><v>1</v></c></row></sheetData>';

/**
 * B2:D6   a picture, red on the left and blue on the right (128 x 80 px at 64, 20)
 * A8:A10  a green rectangle with a black outline
 * B8:C10  a green ellipse
 * A12:B15 the placeholder of a chart
 * C12:D15 a white box with text
 */
const shapesWorkbook = once(() =>
  drawingWorkbook({
    sheet: cells,
    media: { rIdImg: twoColours() },
    drawing:
      twoCell([1, 1], [3, 5], pic('rIdImg', { name: 'Logo' })) +
      twoCell([0, 7], [1, 10], sp({ props: solid('00B050') + outline('000000', 2) })) +
      twoCell([1, 7], [3, 10], sp({ prst: 'ellipse', props: solid('00B050') })) +
      twoCell([0, 11], [2, 15], chartFrame()) +
      twoCell([2, 11], [4, 15], sp({ props: solid('FFFFFF') + outline('000000', 1), body: txBody(para(run('Merhaba dünya', 'sz="1100" b="1"', solid('000000')))) })),
  }),
);

async function mount(page: Page, bytes: Uint8Array, options: Record<string, unknown> = {}, query = ''): Promise<void> {
  await page.goto(`/e2e/pages/view.html${query}`);
  await page.waitForFunction(() => typeof (window as any).__mountView === 'function');
  await page.evaluate(
    async ({ base64, options }) => {
      const text = atob(base64);
      const data = new Uint8Array(text.length);
      for (let i = 0; i < text.length; i++) data[i] = text.charCodeAt(i);
      await (window as any).__mountView(data, options);
    },
    { base64: Buffer.from(bytes).toString('base64'), options: { locale: 'en-US', ...options } },
  );
  await expect(page.locator('.bym-canvas')).toBeVisible();
}

const canvasOf = (page: Page) =>
  page.evaluateHandle(() => {
    const shadow = (window as any).__shadow as ShadowRoot | null;
    return (shadow || document).querySelector('.bym-canvas') as HTMLCanvasElement;
  });

/** Colour of one canvas pixel (CSS coordinates relative to the canvas) after a forced redraw. */
function pixel(page: Page, x: number, y: number): Promise<number[]> {
  return page.evaluate(
    ([x, y]) => {
      const view = (window as any).__view;
      view.render();
      const shadow = (window as any).__shadow as ShadowRoot | null;
      const canvas = (shadow || document).querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      return Array.from(canvas.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), 1, 1).data).slice(0, 3);
    },
    [x, y],
  );
}

/** Number of pixels of a canvas rectangle (CSS coordinates) that are darker than `limit` in every channel. */
function darkPixels(page: Page, x: number, y: number, width: number, height: number, limit = 100): Promise<number> {
  return page.evaluate(
    ([x, y, width, height, limit]) => {
      const view = (window as any).__view;
      view.render();
      const canvas = document.querySelector('.bym-canvas') as HTMLCanvasElement;
      const dpr = view.getViewState().devicePixelRatio;
      const data = canvas.getContext('2d')!.getImageData(Math.round(x * dpr), Math.round(y * dpr), Math.round(width * dpr), Math.round(height * dpr)).data;
      let count = 0;
      for (let i = 0; i < data.length; i += 4) if (data[i] < limit && data[i + 1] < limit && data[i + 2] < limit) count++;
      return count;
    },
    [x, y, width, height, limit],
  );
}

/** A point of the sheet on the canvas: `col` and `row` may be fractions. */
const at = (col: number, row: number) => ({ x: HEADER_WIDTH + col * COLUMN_WIDTH, y: HEADER_HEIGHT + row * ROW_HEIGHT });

const colourAt = (page: Page, col: number, row: number) => {
  const point = at(col, row);
  return pixel(page, point.x, point.y);
};

/** Waits until a pixel has a colour: pictures are decoded after the first frame. */
const expectColour = (page: Page, col: number, row: number, colour: number[]) => expect.poll(() => colourAt(page, col, row), { timeout: 10_000 }).toEqual(colour);

const view = (page: Page, code: string) => page.evaluate((code) => new Function('view', `return ${code}`)((window as any).__view), code);

const live = (page: Page) => page.locator('.bym-live');

test.describe('drawings of a sheet', () => {
  test('a picture, shapes, text and the placeholder of a chart are drawn above the cells', async ({ page }) => {
    await mount(page, await shapesWorkbook());

    // The picture: 128 x 80 at B2, its left half red and its right half blue.
    await expectColour(page, 1.2, 2, RED);
    expect(await colourAt(page, 1.9, 4.5)).toEqual(RED);
    expect(await colourAt(page, 2.1, 1.3)).toEqual(BLUE);
    expect(await colourAt(page, 2.9, 4.8)).toEqual(BLUE);
    // Nothing of it outside its anchor.
    expect(await colourAt(page, 0.8, 2)).toEqual(WHITE);
    expect(await colourAt(page, 3.2, 2)).toEqual(WHITE);
    expect(await colourAt(page, 2, 0.6)).toEqual(WHITE);
    expect(await colourAt(page, 2, 5.4)).toEqual(WHITE);

    // The rectangle: green inside, a black outline of two pixels at its edge.
    expect(await colourAt(page, 0.5, 8.5)).toEqual(GREEN);
    const edge = at(0, 8.5);
    expect(await pixel(page, edge.x, edge.y)).toEqual([0, 0, 0]);
    // The ellipse: green in the middle, the sheet in the corners of its box.
    expect(await colourAt(page, 2, 8.5)).toEqual(GREEN);
    const corner = at(1, 7);
    expect(await pixel(page, corner.x + 3, corner.y + 3)).toEqual(WHITE);
    expect(await pixel(page, corner.x + 125, corner.y + 57)).toEqual(WHITE);

    // The chart: a grey box with a word in it.
    expect(await colourAt(page, 0.1, 11.3)).toEqual(PLACEHOLDER);
    const chart = at(0, 11);
    expect(await darkPixels(page, chart.x + 20, chart.y + 30, 88, 20, 130)).toBeGreaterThan(10);

    // The text box: black text on white, near its top left corner.
    const box = at(2, 11);
    expect(await darkPixels(page, box.x + 8, box.y + 4, 110, 22)).toBeGreaterThan(40);
    // And none in its lower half.
    expect(await darkPixels(page, box.x + 8, box.y + 50, 110, 20)).toBe(0);

    expect(await view(page, 'view.getDrawingState().objects')).toBe(5);
  });

  test('the selection is drawn over a picture, the headers stay above it', async ({ page }) => {
    await mount(page, await shapesWorkbook());
    await expectColour(page, 1.2, 2, RED);
    await view(page, 'view.select({ top: 1, left: 1, bottom: 2, right: 1 })');
    // The border of the selection, two pixels at the left edge of B2, is not the picture's red.
    const edge = at(1, 1.5);
    const border = await pixel(page, edge.x, edge.y);
    expect(border).not.toEqual(RED);
    expect(border[1]).toBeGreaterThan(90);
    // Scrolled half a row: the picture goes under the column header, not over it.
    await view(page, 'view.scrollTo(4, 0)');
    const header = await pixel(page, HEADER_WIDTH + 1.5 * COLUMN_WIDTH + 20, 4);
    expect(header).not.toEqual(RED);
    expect(header[0]).toBeGreaterThan(200);
  });

  test('crop, flips and rotation of a picture', async ({ page }) => {
    await mount(
      page,
      await drawingWorkbook({
        sheet: cells,
        media: { rIdImg: twoColours() },
        drawing:
          // The left half cut off: all blue.
          twoCell([0, 1], [2, 4], pic('rIdImg', { fill: '<a:srcRect l="50000"/><a:stretch><a:fillRect/></a:stretch>' })) +
          // Mirrored: blue on the left.
          twoCell([2, 1], [4, 4], pic('rIdImg', { xfrm: 'flipH="1"' })) +
          // Turned half way round: blue on the left as well.
          twoCell([0, 5], [2, 8], pic('rIdImg', { xfrm: 'rot="10800000"' })) +
          // A quarter turn clockwise: red on top. The anchor (128 x 60) holds the turned picture.
          twoCell([2, 5], [4, 8], pic('rIdImg', { xfrm: 'rot="5400000"' })),
      }),
    );
    await expectColour(page, 0.3, 2, BLUE);
    expect(await colourAt(page, 1.7, 2)).toEqual(BLUE);
    await expectColour(page, 2.3, 2, BLUE);
    expect(await colourAt(page, 3.7, 2)).toEqual(RED);
    await expectColour(page, 0.3, 6, BLUE);
    expect(await colourAt(page, 1.7, 6)).toEqual(RED);
    // Turned, the picture fills its anchor (128 x 60): what was its left half is the upper half now.
    await expectColour(page, 3, 5.2, RED);
    expect(await colourAt(page, 2.1, 5.8)).toEqual(RED);
    expect(await colourAt(page, 3.9, 5.8)).toEqual(RED);
    expect(await colourAt(page, 2.1, 7.2)).toEqual(BLUE);
    expect(await colourAt(page, 3.9, 7.8)).toEqual(BLUE);
    // And nothing of it above or below the anchor.
    expect(await colourAt(page, 3, 4.6)).toEqual(WHITE);
    expect(await colourAt(page, 3, 8.4)).toEqual(WHITE);
  });

  test('a group places its members; a connector is a line', async ({ page }) => {
    await mount(
      page,
      await drawingWorkbook({
        sheet: cells,
        drawing:
          twoCell(
            [0, 1],
            [2, 5],
            group(
              xfrm(0, 0, 100, 100, '', [0, 0, 100, 100]),
              sp({ xfrm: xfrm(0, 0, 50, 50), props: solid('DC0000') }) + sp({ xfrm: xfrm(50, 50, 50, 50), props: solid('0000DC') }),
            ),
          ) +
          // A horizontal line three pixels thick, through the middle of row 8.
          '<xdr:twoCellAnchor>' +
          '<xdr:from><xdr:col>0</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>7</xdr:row><xdr:rowOff>95250</xdr:rowOff></xdr:from>' +
          '<xdr:to><xdr:col>2</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>7</xdr:row><xdr:rowOff>95250</xdr:rowOff></xdr:to>' +
          `${connector(outline('0000DC', 3))}<xdr:clientData/></xdr:twoCellAnchor>`,
      }),
    );
    // The group is 128 x 80 at A2: red in its top left quarter, blue in its bottom right one, nothing in the others.
    expect(await colourAt(page, 0.5, 2)).toEqual(RED);
    expect(await colourAt(page, 1.5, 4)).toEqual(BLUE);
    expect(await colourAt(page, 1.5, 2)).toEqual(WHITE);
    expect(await colourAt(page, 0.5, 4)).toEqual(WHITE);
    expect(await colourAt(page, 1, 7.5)).toEqual(BLUE);
    expect(await colourAt(page, 1, 7.2)).toEqual(WHITE);
    expect(await colourAt(page, 2.2, 7.5)).toEqual(WHITE);
  });

  test('what is not a raster picture is never given to the browser: a placeholder, and no request', async ({ page }) => {
    const requests: string[] = [];
    page.on('request', (request) => requests.push(request.url()));
    const svg = new TextEncoder().encode(
      '<svg xmlns="http://www.w3.org/2000/svg" width="40" height="20"><image href="http://127.0.0.1:9/leak.png" width="40" height="20"/><rect width="40" height="20" fill="#dc0000"/></svg>',
    );
    const emf = new Uint8Array(200);
    emf.set([1, 0, 0, 0, 108, 0, 0, 0]);
    emf.set([0x20, 0x45, 0x4d, 0x46], 40);
    await mount(
      page,
      await drawingWorkbook({
        sheet: cells,
        media: { rIdSvg: svg, rIdEmf: emf, rIdImg: twoColours() },
        drawing:
          twoCell([0, 1], [2, 4], pic('rIdSvg', { name: 'Vector' })) +
          twoCell([2, 1], [4, 4], pic('rIdEmf')) +
          twoCell([0, 5], [2, 8], pic('rIdLink', { link: true })) +
          twoCell([2, 5], [4, 8], pic('rIdImg')),
        drawingRels:
          '<Relationship Id="rIdLink" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="http://127.0.0.1:9/outside.png" TargetMode="External"/>',
      }),
    );
    // The raster picture arrives; by then the others have been looked at too.
    await expectColour(page, 2.3, 6, RED);
    await expectColour(page, 0.1, 1.2, PLACEHOLDER);
    await expectColour(page, 2.1, 1.2, PLACEHOLDER);
    await expectColour(page, 0.1, 5.2, PLACEHOLDER);
    // Nothing of the SVG was drawn.
    expect(await colourAt(page, 1, 3.5)).not.toEqual(RED);
    expect(await page.locator('img, image, object, embed, iframe').count()).toBe(0);
    expect(requests.filter((url) => url.indexOf('127.0.0.1:9') >= 0 || /^(blob|data):/.test(url) === false && !/\/(e2e|dist)\//.test(url) && !/favicon/.test(url))).toEqual([]);
  });

  test('a picture follows scrolling and is cut at the headers', async ({ page }) => {
    await mount(page, await shapesWorkbook());
    await expectColour(page, 1.2, 2, RED);
    // Two rows down and one column to the right: the picture is at A0..C4 of the window now.
    await view(page, 'view.scrollTo(4, 4)');
    await page.evaluate(() => {
      const scroller = document.querySelector('.bym-scroller') as HTMLElement;
      scroller.scrollTop = 40;
      scroller.scrollLeft = 64;
    });
    await expect.poll(() => view(page, 'view.getViewState().scrollY')).toBe(40);
    await expect.poll(() => view(page, 'view.getViewState().scrollX')).toBe(64);
    // B2 of the sheet is where A0 would be: its lower rows show from the top of the cell area.
    await expectColour(page, 0.5, 0.5, RED);
    expect(await colourAt(page, 1.5, 2.5)).toEqual(BLUE);
    expect(await colourAt(page, 1.5, 3.4)).toEqual(WHITE);
    // The headers are not painted over.
    expect(await pixel(page, HEADER_WIDTH + 30, 3)).not.toEqual(RED);
    expect(await pixel(page, 3, HEADER_HEIGHT + 30)).not.toEqual(RED);
  });

  test('with frozen panes each pane shows its own part of a picture', async ({ page }) => {
    // Rows 1 to 3 and column A are frozen; the picture lies across both boundaries (A2:C6).
    await mount(
      page,
      await drawingWorkbook({
        sheet: '<sheetViews><sheetView workbookViewId="0"><pane xSplit="1" ySplit="3" topLeftCell="B4" activePane="bottomRight" state="frozen"/></sheetView></sheetViews>' + cells,
        media: { rIdImg: twoColours() },
        drawing: twoCell([0, 1], [2, 5], pic('rIdImg')),
      }),
    );
    await expectColour(page, 0.5, 2, RED);
    expect(await colourAt(page, 1.5, 2)).toEqual(BLUE);
    expect(await colourAt(page, 1.5, 4.5)).toEqual(BLUE);

    // One row down: the frozen rows keep their part; the part below slides under them.
    await view(page, 'view.scrollTo(4 + 20, 1)');
    await page.evaluate(() => ((document.querySelector('.bym-scroller') as HTMLElement).scrollTop = 20));
    await expect.poll(() => view(page, 'view.getViewState().scrollY')).toBe(20);
    expect(await colourAt(page, 0.5, 2)).toEqual(RED);
    expect(await colourAt(page, 1.5, 2.5)).toEqual(BLUE);
    // Row 4 of the sheet is gone from view; row 5 and 6 follow the frozen rows directly, so the picture ends a row earlier.
    expect(await colourAt(page, 1.5, 3.5)).toEqual(BLUE);
    expect(await colourAt(page, 1.5, 4.5)).toEqual(WHITE);
    expect(await colourAt(page, 0.5, 4.5)).toEqual(WHITE);

    // One column to the right as well: column A keeps the red part, the blue part of column B is gone.
    await page.evaluate(() => ((document.querySelector('.bym-scroller') as HTMLElement).scrollLeft = 64));
    await expect.poll(() => view(page, 'view.getViewState().scrollX')).toBe(64);
    expect(await colourAt(page, 0.5, 2)).toEqual(RED);
    expect(await colourAt(page, 1.5, 2)).toEqual(WHITE);
  });

  test('inserted and deleted rows move a picture; undo moves it back; the saved file has it there', async ({ page }) => {
    await mount(page, await shapesWorkbook());
    await expectColour(page, 1.2, 2, RED);
    await view(page, 'view.insertRows(0, 2)');
    // Two rows lower.
    await expectColour(page, 1.2, 4, RED);
    // Where it was: the sheet (tinted by the selection of the new rows).
    expect(await colourAt(page, 1.2, 1.5)).not.toEqual(RED);
    expect(await colourAt(page, 2.8, 6.5)).toEqual(BLUE);
    expect(await colourAt(page, 2.8, 7.4)).toEqual(WHITE);

    // Rows inserted inside make it taller: it moves and sizes with cells.
    await view(page, 'view.insertRows(5, 1)');
    await expectColour(page, 2.8, 7.4, BLUE);

    // The anchor the view works with is the one the writer puts into the file (the unit tests compare the two).
    const shown = await page.evaluate(() => {
      const api = (window as any).BymOffice;
      return new api.SheetDrawings((window as any).__view.workbook.sheets[0]).currentAnchors()[0];
    });
    expect(shown.from).toEqual({ col: 1, colOff: 0, row: 3, rowOff: 0 });
    expect(shown.to).toEqual({ col: 3, colOff: 0, row: 8, rowOff: 0 });

    await view(page, 'view.undo()');
    await view(page, 'view.undo()');
    await expectColour(page, 1.2, 2, RED);
    expect(await colourAt(page, 2.8, 5.4)).toEqual(WHITE);

    await view(page, 'view.deleteRows(0, 1)');
    await expectColour(page, 1.2, 0.5, RED);
    expect(await colourAt(page, 1.2, 4.5)).toEqual(WHITE);
  });

  test('hidden rows squeeze a picture that sizes with cells', async ({ page }) => {
    await mount(
      page,
      await drawingWorkbook({
        sheet: '<sheetData><row r="3" hidden="1"/><row r="4" hidden="1"/></sheetData>',
        media: { rIdImg: twoColours() },
        drawing: twoCell([1, 1], [3, 5], pic('rIdImg')),
      }),
    );
    // Rows 3 and 4 are gone: the picture is 40 px high instead of 80.
    await expectColour(page, 1.2, 1.5, RED);
    const top = at(1.2, 1);
    expect(await pixel(page, top.x, top.y + 35)).toEqual(RED);
    expect(await pixel(page, top.x, top.y + 45)).toEqual(WHITE);
  });

  test('a damaged picture is a placeholder; the others are shown; the page stays quiet', async ({ page }) => {
    // The header of a picture, and then nothing a decoder can use.
    const broken = new Uint8Array(120).fill(0xff);
    broken.set(twoColours().slice(0, 33));
    await mount(
      page,
      await drawingWorkbook({
        sheet: cells,
        media: { rIdBad: broken, rIdImg: twoColours() },
        drawing: twoCell([0, 1], [2, 4], pic('rIdBad')) + twoCell([2, 1], [4, 4], pic('rIdImg')),
      }),
    );
    await expectColour(page, 2.3, 2, RED);
    await expectColour(page, 0.1, 1.2, PLACEHOLDER);
  });

  test('an object that cannot be read is left out; the others are shown and the host is told once', async ({ page }) => {
    const broken = '<xdr:twoCellAnchor><xdr:from><xdr:col>x</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>0</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from><xdr:clientData/></xdr:twoCellAnchor>';
    await mount(page, await drawingWorkbook({ sheet: cells, drawing: broken + twoCell([1, 1], [3, 5], sp({ props: solid('DC0000') })) }));
    expect(await colourAt(page, 2, 3)).toEqual(RED);
    await expect.poll(() => page.evaluate(() => (window as any).__notices)).toEqual([{ message: 'Some drawings or comments of this sheet could not be read and are not shown', kind: 'info' }]);
    expect(await view(page, 'view.workbook.sheets[0].warnings')).toEqual(['Drawing: 1 object(s) could not be read and are not shown']);
  });

  test('decoded pictures stay within the budget and are given back on destroy', async ({ page }) => {
    await mount(page, await shapesWorkbook());
    await expectColour(page, 1.2, 2, RED);
    const state = (await view(page, 'view.getDrawingState()')) as { imageBytes: number; imageBudget: number };
    expect(state.imageBytes).toBeGreaterThan(0);
    expect(state.imageBytes).toBeLessThanOrEqual(state.imageBudget);
    await view(page, 'view.destroy()');
    expect(await view(page, 'view.getDrawingState()')).toEqual({ objects: 0, imageBytes: 0, imageBudget: 0 });
  });

  test('a sheet without drawings pays nothing for the layer', async ({ page }) => {
    // The same 60 frames over a sheet of plain cells, with and without a drawing far away from what is shown.
    let rows = '';
    for (let r = 1; r <= 400; r++) rows += `<row r="${r}"><c r="A${r}"><v>${r}</v></c><c r="B${r}"><v>${r * 2}</v></c><c r="C${r}"><v>${r * 3}</v></c></row>`;
    // Timers in a browser are coarse: many frames are timed together and the mean is taken.
    const frames = () =>
      page.evaluate(() => {
        const view = (window as any).__view;
        const scroller = document.querySelector('.bym-scroller') as HTMLElement;
        const start = performance.now();
        for (let round = 0; round < 10; round++) {
          for (let i = 0; i < 60; i++) {
            scroller.scrollTop = i * 100;
            view.render();
          }
        }
        return (performance.now() - start) / 600;
      });
    await mount(page, await drawingWorkbook({ sheet: `<sheetData>${rows}</sheetData>` }));
    expect(await view(page, 'view.getDrawingState().objects')).toBe(0);
    const plain = await frames();
    await mount(page, await drawingWorkbook({ sheet: `<sheetData>${rows}</sheetData>`, drawing: twoCell([1, 5000], [3, 5004], sp({ props: solid('DC0000') })) }));
    expect(await view(page, 'view.getDrawingState().objects')).toBe(1);
    const far = await frames();
    console.log(`frame of plain cells, mean of 600 [${test.info().project.name}]: ${plain.toFixed(3)} ms without drawings, ${far.toFixed(3)} ms with one out of sight`);
    // A drawing out of sight costs a lookup; generous bounds, the numbers are in the log.
    expect(far).toBeLessThan(plain * 2 + 3);
  });

  test('a sheet of a thousand pictures scrolls without a slow frame', async ({ page }) => {
    // 4 across, 250 down, every picture 56 x 36 in its own block of two rows. All of them show the same part.
    let anchors = '';
    for (let i = 0; i < 1000; i++) anchors += twoCell([i % 4, Math.floor(i / 4) * 2, 4, 2], [i % 4, Math.floor(i / 4) * 2 + 1, 60, 18], pic('rIdImg'));
    await mount(page, await drawingWorkbook({ sheet: cells, media: { rIdImg: twoColours() }, drawing: anchors }));
    const first = at(0, 0);
    await expect.poll(() => pixel(page, first.x + 10, first.y + 10), { timeout: 10_000 }).toEqual(RED);
    expect(await view(page, 'view.getDrawingState().objects')).toBe(1000);
    // Timers in a browser are coarse: the mean of many frames says more than any one of them.
    const timing = await page.evaluate(() => {
      const view = (window as any).__view;
      const scroller = document.querySelector('.bym-scroller') as HTMLElement;
      let worst = 0;
      const begin = performance.now();
      for (let round = 0; round < 10; round++) {
        for (let i = 0; i < 60; i++) {
          scroller.scrollTop = i * 150;
          const start = performance.now();
          view.render();
          worst = Math.max(worst, performance.now() - start);
        }
      }
      return { mean: (performance.now() - begin) / 600, worst };
    });
    console.log(`1,000 pictures, 600 frames while scrolling [${test.info().project.name}]: mean ${timing.mean.toFixed(3)} ms, worst ${timing.worst.toFixed(2)} ms`);
    expect(timing.mean).toBeLessThan(30);
    // One frame may fall on a collection of garbage on a busy machine; half a second would be something else.
    expect(timing.worst).toBeLessThan(500);
  });
});

/**
 * B2  a note by Ayşe ("Ayşe:" in bold, then the text)
 * C4  a plain note
 * A6  a long note
 * D2  a note whose box is always shown (C6:D9 of the sheet)
 */
const LONG = Array.from({ length: 80 }, (_, i) => `satır ${i + 1} ${'uzunbirsözcük'.repeat(6)}`).join('\n');

const commentsWorkbook = once(() =>
  drawingWorkbook({
    sheet: '<sheetData><row r="2"><c r="B2" t="inlineStr"><is><t>veri</t></is></c></row></sheetData>',
    comments: commentsXml(
      ['Ayşe', 'Bora'],
      comment('B2', 0, '<r><rPr><b/><sz val="9"/><rFont val="Tahoma"/></rPr><t>Ayşe:</t></r><r><rPr><sz val="9"/><rFont val="Tahoma"/></rPr><t xml:space="preserve">\n&lt;b&gt;Kontrol&lt;/b&gt; edildi</t></r>') +
        comment('C4', 1, '<t>Düz not</t>') +
        comment('A6', 1, `<t>${LONG}</t>`) +
        comment('D2', 1, '<t>Hep görünür</t>'),
    ),
    vml: vmlXml(vmlNote(1, 1) + vmlNote(3, 2) + vmlNote(5, 0) + vmlNote(1, 3, { visible: true, anchor: '2, 8, 5, 4, 3, 56, 8, 16' })),
  }),
);

/** The top right corner of a cell, three pixels in: inside the mark of a comment. */
const markAt = (col: number, row: number) => {
  const point = at(col + 1, row);
  return { x: point.x - 3, y: point.y + 1.5 };
};

const box = (page: Page) => page.locator('.bym-comment');

test.describe('comments of a sheet', () => {
  test('a cell with a comment has a red corner; a cell without one has none', async ({ page }) => {
    await mount(page, await commentsWorkbook());
    for (const [col, row] of [
      [1, 1],
      [2, 3],
      [0, 5],
      [3, 1],
    ]) {
      const point = markAt(col, row);
      expect(await pixel(page, point.x, point.y), `mark of ${col},${row}`).toEqual(MARK);
    }
    const none = markAt(2, 1);
    expect(await pixel(page, none.x, none.y)).toEqual(WHITE);
    // The corner is the top right one.
    const left = at(1, 1);
    expect(await pixel(page, left.x + 2, left.y + 1.5)).toEqual(WHITE);
  });

  test('selecting a cell shows its comment beside it, and says it', async ({ page }) => {
    await mount(page, await commentsWorkbook());
    await expect(box(page)).toHaveCount(0);
    await view(page, 'view.select({ top: 1, left: 1, bottom: 1, right: 1 })');
    await expect(box(page)).toBeVisible();
    // Text only: what looks like markup in the file is shown as it is written.
    await expect(box(page)).toHaveText('Ayşe:\n<b>Kontrol</b> edildi');
    expect(await box(page).locator('b').count()).toBe(0);
    // The name is bold, and it is not said twice.
    const author = box(page).locator('.bym-comment-author');
    await expect(author).toHaveText('Ayşe:');
    expect(await author.evaluate((el) => Number(getComputedStyle(el).fontWeight))).toBeGreaterThanOrEqual(600);
    await expect(live(page)).toHaveText('B2 veri. Comment: Ayşe: <b>Kontrol</b> edildi');

    // Beside the cell, inside the view.
    const place = await page.evaluate(() => {
      const rect = (document.querySelector('.bym-comment') as HTMLElement).getBoundingClientRect();
      const host = (document.querySelector('.bym-canvas') as HTMLElement).getBoundingClientRect();
      return { left: rect.left - host.left, top: rect.top - host.top, right: rect.right - host.left, bottom: rect.bottom - host.top, width: host.width, height: host.height };
    });
    expect(place.left).toBeGreaterThanOrEqual(0);
    expect(place.right).toBeLessThanOrEqual(place.width);
    expect(place.bottom).toBeLessThanOrEqual(place.height);
    // To the right of B2 (which ends at 72 + 128) where there is room, else to its left.
    const cellRight = HEADER_WIDTH + 2 * COLUMN_WIDTH;
    if (place.width >= cellRight + 8 + (place.right - place.left) + 4) expect(place.left).toBe(cellRight + 8);

    // Another cell: the box goes; a comment by an author whose name the text does not start with shows the name first.
    await view(page, 'view.select({ top: 3, left: 2, bottom: 3, right: 2 })');
    await expect(box(page)).toHaveText('Bora:\nDüz not');
    await expect(live(page)).toHaveText('C4. Comment: Bora: Düz not');
    await view(page, 'view.select({ top: 9, left: 0, bottom: 9, right: 0 })');
    await expect(box(page)).toHaveCount(0);
    await expect(live(page)).toHaveText('A10');
  });

  test('the comment is shown in a read-only view as well', async ({ page }) => {
    await mount(page, await commentsWorkbook(), { readOnly: true });
    await view(page, 'view.select({ top: 3, left: 2, bottom: 3, right: 2 })');
    await expect(box(page)).toHaveText('Bora:\nDüz not');
  });

  test('pointing at a cell shows its comment; leaving it takes the box away', async ({ page, isMobile }) => {
    test.skip(isMobile, 'a finger does not hover');
    await mount(page, await commentsWorkbook());
    const canvas = await page.locator('.bym-canvas').boundingBox();
    const cell = at(2.5, 3.5);
    await page.mouse.move(canvas!.x + cell.x, canvas!.y + cell.y);
    await expect(box(page)).toHaveText('Bora:\nDüz not');
    // The selection has not moved.
    expect(await view(page, 'view.selection.active')).toEqual({ row: 0, col: 0 });
    const away = at(2.5, 8.5);
    await page.mouse.move(canvas!.x + away.x, canvas!.y + away.y);
    await expect(box(page)).toHaveCount(0);
    // The comment of the pointed cell wins over the one of the active cell.
    await view(page, 'view.select({ top: 1, left: 1, bottom: 1, right: 1 })');
    await expect(box(page)).toContainText('Kontrol');
    await page.mouse.move(canvas!.x + cell.x, canvas!.y + cell.y);
    await expect(box(page)).toHaveText('Bora:\nDüz not');
    await page.mouse.move(canvas!.x + away.x, canvas!.y + away.y);
    await expect(box(page)).toContainText('Kontrol');
  });

  test('a tap on a cell shows its comment', async ({ page, isMobile, browserName }) => {
    test.skip(!isMobile || browserName !== 'chromium', 'real touch events need Chromium with a touch screen');
    await mount(page, await commentsWorkbook());
    const canvas = await page.locator('.bym-canvas').boundingBox();
    const cell = at(2.5, 3.5);
    await page.touchscreen.tap(canvas!.x + cell.x, canvas!.y + cell.y);
    await expect(box(page)).toHaveText('Bora:\nDüz not');
    const other = at(1.5, 6.5);
    await page.touchscreen.tap(canvas!.x + other.x, canvas!.y + other.y);
    await expect(box(page)).toHaveCount(0);
  });

  test('Escape puts the comment of the active cell away until the cell is entered again', async ({ page, isMobile }) => {
    test.skip(isMobile, 'a phone has no Escape key');
    await mount(page, await commentsWorkbook());
    await view(page, 'view.select({ top: 3, left: 2, bottom: 3, right: 2 })');
    await view(page, 'view.focus()');
    await expect(box(page)).toBeVisible();
    await page.keyboard.press('Escape');
    await expect(box(page)).toHaveCount(0);
    await page.keyboard.press('ArrowDown');
    await expect(box(page)).toHaveCount(0);
    await page.keyboard.press('ArrowUp');
    await expect(box(page)).toHaveText('Bora:\nDüz not');
  });

  test('a long comment stays inside the view and scrolls', async ({ page }) => {
    await mount(page, await commentsWorkbook());
    await view(page, 'view.select({ top: 5, left: 0, bottom: 5, right: 0 })');
    await expect(box(page)).toBeVisible();
    const place = await page.evaluate(() => {
      const el = document.querySelector('.bym-comment') as HTMLElement;
      const rect = el.getBoundingClientRect();
      const host = (document.querySelector('.bym-canvas') as HTMLElement).getBoundingClientRect();
      return {
        left: rect.left - host.left,
        top: rect.top - host.top,
        right: rect.right - host.left,
        bottom: rect.bottom - host.top,
        width: host.width,
        height: host.height,
        scrolls: el.scrollHeight > el.clientHeight,
        sideways: el.scrollWidth > el.clientWidth,
        pointer: getComputedStyle(el).pointerEvents,
      };
    });
    expect(place.left).toBeGreaterThanOrEqual(0);
    expect(place.top).toBeGreaterThanOrEqual(0);
    expect(place.right).toBeLessThanOrEqual(place.width);
    expect(place.bottom).toBeLessThanOrEqual(place.height);
    expect(place.bottom - place.top).toBeLessThanOrEqual(240);
    expect(place.right - place.left).toBeLessThanOrEqual(280);
    // The long words are broken; the lines that do not fit are reached by scrolling.
    expect(place.sideways).toBe(false);
    expect(place.scrolls).toBe(true);
    expect(place.pointer).toBe('auto');
    expect(await box(page).evaluate((el) => ((el.scrollTop = 500), el.scrollTop))).toBe(500);
    // Said in short: the live region does not get eighty lines.
    expect(((await live(page).textContent()) || '').length).toBeLessThan(560);
  });

  test('a comment that is always shown is a box on the sheet, not beside the cell', async ({ page }) => {
    await mount(page, await commentsWorkbook());
    // The box: from 8 px into column C, 4 px into row 6, to 56 px into column D, 16 px into row 9.
    const inside = at(2, 5);
    expect(await pixel(page, inside.x + 20, inside.y + 50)).toEqual(NOTE);
    expect(await darkPixels(page, inside.x + 10, inside.y + 6, 100, 16)).toBeGreaterThan(20);
    const outside = at(2, 5);
    expect(await pixel(page, outside.x + 4, outside.y + 2)).toEqual(WHITE);
    await view(page, 'view.select({ top: 1, left: 3, bottom: 1, right: 3 })');
    await expect(box(page)).toHaveCount(0);
    await expect(live(page)).toHaveText('D2. Comment: Bora: Hep görünür');
  });

  test('comments follow inserted and deleted rows', async ({ page }) => {
    await mount(page, await commentsWorkbook());
    await view(page, 'view.insertRows(0, 2)');
    const moved = markAt(1, 3);
    expect(await pixel(page, moved.x, moved.y)).toEqual(MARK);
    const old = markAt(1, 1);
    await view(page, 'view.select({ top: 3, left: 1, bottom: 3, right: 1 })');
    expect(await pixel(page, old.x, old.y)).toEqual(WHITE);
    await expect(box(page)).toContainText('Kontrol');
    // The row of a comment deleted: the comment is gone.
    await view(page, 'view.deleteRows(3, 1)');
    await expect(box(page)).toHaveCount(0);
    expect(await pixel(page, moved.x, moved.y)).toEqual(WHITE);
    await view(page, 'view.undo()');
    expect(await pixel(page, moved.x, moved.y)).toEqual(MARK);
  });

  test('the comment of a merged cell is marked in the corner of the merge and shown from any of its cells', async ({ page, isMobile }) => {
    await mount(
      page,
      await drawingWorkbook({
        sheet: '<sheetData/><mergeCells count="1"><mergeCell ref="B2:C3"/></mergeCells>',
        comments: commentsXml(['Bora'], comment('B2', 0, '<t>Birleşik</t>')),
      }),
    );
    const corner = markAt(2, 1);
    expect(await pixel(page, corner.x, corner.y)).toEqual(MARK);
    const inner = markAt(1, 1);
    expect(await pixel(page, inner.x, inner.y)).toEqual(WHITE);
    if (!isMobile) {
      const canvas = await page.locator('.bym-canvas').boundingBox();
      const cell = at(2.5, 2.5);
      await page.mouse.move(canvas!.x + cell.x, canvas!.y + cell.y);
      await expect(box(page)).toHaveText('Bora:\nBirleşik');
    }
  });

  test('inside a shadow root and under a CSS transform the box is still beside its cell', async ({ page }) => {
    await mount(page, await commentsWorkbook(), { shadow: 'open' });
    await page.evaluate(() => {
      const host = document.getElementById('host') as HTMLElement;
      host.style.transform = 'scale(0.8)';
      host.style.transformOrigin = '0 0';
    });
    await view(page, 'view.select({ top: 3, left: 2, bottom: 3, right: 2 })');
    await page.waitForFunction(() => ((window as any).__shadow as ShadowRoot).querySelector('.bym-comment') !== null);
    const place = await page.evaluate(() => {
      const shadow = (window as any).__shadow as ShadowRoot;
      const el = shadow.querySelector('.bym-comment') as HTMLElement;
      const canvas = shadow.querySelector('.bym-canvas') as HTMLElement;
      const rect = el.getBoundingClientRect();
      const host = canvas.getBoundingClientRect();
      return { text: el.textContent, left: (rect.left - host.left) / 0.8, top: (rect.top - host.top) / 0.8, right: (rect.right - host.left) / 0.8, width: host.width / 0.8, background: getComputedStyle(el).backgroundColor };
    });
    expect(place.text).toBe('Bora:\nDüz not');
    // The style of the box reaches into the shadow root.
    expect(place.background).toBe('rgb(255, 255, 225)');
    expect(place.left).toBeGreaterThanOrEqual(0);
    expect(place.right).toBeLessThanOrEqual(place.width + 0.5);
    // Level with row 4 (which starts at 22 + 60), four pixels above it.
    expect(Math.abs(place.top - (HEADER_HEIGHT + 3 * ROW_HEIGHT - 4))).toBeLessThanOrEqual(1);
    const handle = await canvasOf(page);
    expect(await handle.evaluate((canvas) => canvas.isConnected)).toBe(true);
  });

  test('the words of the view follow its language', async ({ page }) => {
    await mount(
      page,
      await drawingWorkbook({ sheet: cells, drawing: twoCell([0, 1], [3, 6], chartFrame()), comments: commentsXml(['Bora'], comment('A1', 0, '<t>not</t>')) }),
      { locale: 'tr' },
    );
    await view(page, 'view.select({ top: 0, left: 0, bottom: 0, right: 0 })');
    await view(page, 'view.select({ top: 1, left: 0, bottom: 1, right: 0 })');
    await view(page, 'view.select({ top: 0, left: 0, bottom: 0, right: 0 })');
    await expect(live(page)).toHaveText('A1 1. Yorum: Bora: not');
    await expect(box(page)).toHaveAttribute('aria-label', 'Yorum');
  });
});
